import{_ as e,c as a,o as r,ag as i}from"./chunks/framework.Vyheyqg9.js";const h=JSON.parse('{"title":"Node.js practice","description":"","frontmatter":{},"headers":[],"relativePath":"practice/node-js/index.md","filePath":"practice/node-js/index.md"}'),d={name:"practice/node-js/index.md"};function n(o,t,s,c,l,p){return r(),a("div",null,[...t[0]||(t[0]=[i('<h1 id="node-js-practice" tabindex="-1">Node.js practice <a class="header-anchor" href="#node-js-practice" aria-label="Permalink to “Node.js practice”">​</a></h1><p><strong>Learner status: still required for every task.</strong> These specifications apply the explanations; supplied example checks do not complete independent practice.</p><p>Start with the <a href="./../../node-js/">Node.js course</a>. JavaScript values, functions, scope, arrays/objects and basic promises are prerequisites. Runtime exercises need Node and a terminal, not Express, a database or cloud access.</p><p>Start with <a href="./core-project.html">the bounded log analyzer</a>: a small CLI, then one loopback HTTP service, with explicit checkpoints for files, streams, cancellation, testing, diagnostics and shutdown. Its N-01–06 criteria are independent learner work and feed the existing P-332 project.</p><h2 id="topic-to-practice-map" tabindex="-1"><span class="hub-section-number">1 </span>Topic-to-practice map <a class="header-anchor" href="#topic-to-practice-map" aria-label="Permalink to “1 Topic-to-practice map”">​</a></h2><p>Core prerequisites are the JavaScript basics above plus each preceding runtime chapter. Backend rows additionally require HTTP/validation; persistence rows require SQL and an authorized disposable database; delivery rows require a working service and an explicitly owned environment. Read the linked specification&#39;s exact setup before executing a destructive fixture.</p><p>Every row uses the shared evidence record below plus its specific observable acceptance/failure criteria. Parent projects reuse one coherent application; these are focused exercises, not a requirement for 30 unrelated products.</p><table tabindex="0"><thead><tr><th>Topic</th><th>Ready-to-use exercises</th><th>Integration and scope</th></tr></thead><tbody><tr><td>A Minimal AWS Service Slice: Topology, IAM and Cost</td><td><a href="./aws-service-slice.html">Specification</a></td><td>P-333; delivery/recovery continuation, cloud/cluster optional</td></tr><tr><td>Browser CSP: Nonces, Reports and Deployment Evidence</td><td><a href="./browser-csp.html">Specification</a></td><td>P-331; focused API/data/security extension</td></tr><tr><td>An Executed Node/PostgreSQL Container Lab</td><td><a href="./container-deployment-lab.html">Specification</a></td><td>P-333; delivery/recovery continuation, cloud/cluster optional</td></tr><tr><td>Deterministic Cursor Pagination</td><td><a href="./cursor-pagination.html">Specification</a></td><td>P-331; focused API/data/security extension</td></tr><tr><td>PostgreSQL Backup, Restore and Recovery</td><td><a href="./database-recovery.html">Specification</a></td><td>P-333; delivery/recovery continuation, cloud/cluster optional</td></tr><tr><td>Dates, Instants, Time Zones and Calendar Rules</td><td><a href="./dates-and-time-zones.html">Specification</a></td><td>P-331; focused API/data/security extension</td></tr><tr><td>Deploy, restore and roll back a small complete stack</td><td><a href="./full-stack-deployment.html">Specification</a></td><td>P-333; delivery/recovery continuation, cloud/cluster optional</td></tr><tr><td>GraphQL: a bounded catalogue query</td><td><a href="./graphql-basics.html">Specification</a></td><td>P-331/P-332; requirement-driven alternative, not core prerequisite</td></tr><tr><td>Durable jobs and scheduled work</td><td><a href="./jobs-and-schedules.html">Specification</a></td><td>P-331/P-333; optional durable-work continuation</td></tr><tr><td>Node.js Foundations</td><td><a href="./module-01-nodejs-foundations.html">Specification</a></td><td>P-332 / N-01–06; core runtime, HTTP, tests or diagnosis</td></tr><tr><td>Node.js Standard Library</td><td><a href="./module-02-standard-library.html">Specification</a></td><td>P-332 / N-01–06; core runtime, HTTP, tests or diagnosis</td></tr><tr><td>EventEmitter, Buffers, and Streams</td><td><a href="./module-03-events-buffers-streams.html">Specification</a></td><td>P-332 / N-01–06; core runtime, HTTP, tests or diagnosis</td></tr><tr><td>Testing Node.js Applications</td><td><a href="./module-04-testing.html">Specification</a></td><td>P-332 / N-01–06; core runtime, HTTP, tests or diagnosis</td></tr><tr><td>Networking in Node.js</td><td><a href="./module-05-networking.html">Specification</a></td><td>P-332 / N-01–06; core runtime, HTTP, tests or diagnosis</td></tr><tr><td>Express and Layered Architecture</td><td><a href="./module-06-express-architecture.html">Specification</a></td><td>P-331; backend/persistence/identity continuation</td></tr><tr><td>NoSQL Databases, MongoDB, and Mongoose</td><td><a href="./module-07-mongodb-mongoose.html">Specification</a></td><td>P-331/P-332; requirement-driven alternative, not core prerequisite</td></tr><tr><td>Relational Databases, PostgreSQL, and MikroORM</td><td><a href="./module-08-postgresql-mikroorm.html">Specification</a></td><td>P-331; backend/persistence/identity continuation</td></tr><tr><td>Authentication and Authorization</td><td><a href="./module-09-authentication-authorization.html">Specification</a></td><td>P-331; backend/persistence/identity continuation</td></tr><tr><td>Production-Ready Node.js Applications</td><td><a href="./module-10-production-ready-applications.html">Specification</a></td><td>N-06 / P-331 and P-333; lifecycle first, deployment later</td></tr><tr><td>Performance and Diagnostics</td><td><a href="./module-11-performance-diagnostics.html">Specification</a></td><td>P-332 / N-01–06; core runtime, HTTP, tests or diagnosis</td></tr><tr><td>Resilient Architecture and Distributed Systems</td><td><a href="./module-12-resilient-distributed-systems.html">Specification</a></td><td>P-331/P-333; optional durable-work continuation</td></tr><tr><td>OIDC Login Transactions and Signed CSRF Tokens</td><td><a href="./oidc-and-csrf-lab.html">Specification</a></td><td>P-331/P-332; requirement-driven alternative, not core prerequisite</td></tr><tr><td>SSE, Bounded Polling and gRPC: Choosing a Transport</td><td><a href="./realtime-transports.html">Specification</a></td><td>P-331/P-332; requirement-driven alternative, not core prerequisite</td></tr><tr><td>Redis Adapters: Cache Boundaries and Shared Limits</td><td><a href="./redis-adapters.html">Specification</a></td><td>P-331/P-332; requirement-driven alternative, not core prerequisite</td></tr><tr><td>Build Artifacts and Database Rollback Compatibility</td><td><a href="./release-artifact-compatibility.html">Specification</a></td><td>P-333; delivery/recovery continuation, cloud/cluster optional</td></tr><tr><td>REST contracts: OpenAPI, runtime schemas and drift checks</td><td><a href="./rest-contract-workbench.html">Specification</a></td><td>P-331; focused API/data/security extension</td></tr><tr><td>Retention, Expiry and Enforced Deletion</td><td><a href="./retention-and-deletion.html">Specification</a></td><td>P-331; focused API/data/security extension</td></tr><tr><td>A Bounded Text Upload and Its Threat Model</td><td><a href="./safe-text-uploads.html">Specification</a></td><td>P-331; focused API/data/security extension</td></tr><tr><td>Verify signed webhooks before applying effects</td><td><a href="./signed-webhooks.html">Specification</a></td><td>P-331; focused API/data/security extension</td></tr><tr><td>SQL Query Workbench: From Rows to Reports</td><td><a href="./sql-query-workbench.html">Specification</a></td><td>P-331; focused API/data/security extension</td></tr></tbody></table><h2 id="evidence-and-progression" tabindex="-1"><span class="hub-section-number">2 </span>Evidence and progression <a class="header-anchor" href="#evidence-and-progression" aria-label="Permalink to “2 Evidence and progression”">​</a></h2><p>Use a disposable learner directory, synthetic fixtures and the chapter&#39;s runtime assumptions. Keep application/template scripts and database configuration unchanged; never change restricted <code>src/tests</code>.</p><p>For each task record the actual source revision, runtime/lockfile, expected and observed result, failing counterexample, correction, resource cleanup and unperformed checks. Do not prefill success. See the <a href="./../learning-projects.html#retain-a-real-evidence-record">evidence record</a>.</p><p>The <a href="./../backend-project.html">backend project</a> already specifies <strong>P-332</strong> for integrated runtime/stream failure practice, <strong>P-331</strong> for a separate authenticated API/database continuation and <strong>P-333</strong> for deployment/recovery. Their learner status remains outstanding.</p>',12)])])}const f=e(d,[["render",n]]);export{h as __pageData,f as default};
